"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["64775"],{86210(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.fase_com_mais_de_uma_banca_da_segunda_instancia","status":422,"titulo":"A fase prev\xea mais de uma banca que julga o recurso em 2\xaa inst\xe2ncia"},"descricao":{"codigo":"uniplus.selecao.banca.fase_com_mais_de_uma_banca_da_segunda_instancia","requisitos":["UNI-REQ-0454"],"oQueAconteceu":["A fase prev\xea duas ou mais bancas com o papel de julgar o recurso em 2\xaa inst\xe2ncia.\\nA 2\xaa inst\xe2ncia \xe9 um colegiado \xfanico (UNI-REQ-0454): a fase admite uma \xfanica banca\\ncom esse papel.","A mensagem cita a fase pelo c\xf3digo, a quantidade de bancas com o papel e a\\nsegunda banca, pelo nome do tipo e pelo n\xfamero dela, que \xe9 a primeira a retirar.\\nUma banca na fase e outra numa etapa dela s\xe3o aceitas: a regra conta por lugar.\\nNo lugar em que sai a recusa de banca de 2\xaa inst\xe2ncia sem recurso para\\njulgar, esta recusa n\xe3o sai: primeiro se retiram as bancas que n\xe3o t\xeam recurso\\npara julgar.","A confer\xeancia \xe9 de completude e roda na publica\xe7\xe3o e na retifica\xe7\xe3o em ato\\n\xfanico. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na\\nlista `errors[]`, e aponta o campo `fases[i].bancasRequeridas[p]`, com a\\nidentifica\xe7\xe3o da banca para a tela ligar a recusa \xe0 banca certa."],"comoResolver":["Mantenha uma banca de 2\xaa inst\xe2ncia na fase e retire as demais, a come\xe7ar pela que\\na mensagem cita. Se as duas bancas faziam trabalho diferente, uma delas n\xe3o \xe9 de\\n2\xaa inst\xe2ncia: troque o tipo dela.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_uma_banca_da_segunda_instancia_por_fase_ou_etapa`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);